        if (steps === k) {
            path.push(grid[x][y]);
            return;
        }

        visited[x][y] = true;

        for (let dir of directions) {
            const nx = x + dir[0];
            const ny = y + dir[1];

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                dfs(nx, ny, steps + 1);
            }
        }

        visited[x][y] = false;
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (!visited[i][j]) {
                dfs(i, j, 1);
                path.sort((a, b) => a - b);
                return path;
            }
        }
    }

